import pandas as pd


def clean(df):
    df = df.copy()

    species_map = {
        'Adelie': 'Adelie',
        'adelie': 'Adelie',
        'Gentoo': 'Gentoo',
        'gentoo': 'Gentoo',
        'Gentto': 'Gentoo',
        'Chinstrap': 'Chinstrap',
        'chinstrap': 'Chinstrap',
    }
    df['species'] = df['species'].map(lambda x: species_map.get(x, x))

    df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
    df = df[(df['flipper_length_mm'] >= 170) & (df['flipper_length_mm'] <= 235)]

    return df


def answer(df):
    result = {}
    grouped = df.groupby('species')['flipper_length_mm'].mean()
    for species, value in grouped.items():
        if pd.notna(value):
            result[str(species)] = float(value)
    return result
